import sys,os,subprocess,tempfile
W=sys.argv[1]; sys.path.insert(0,W)
from fcheck import footer_problem,F
pos={'one blank line':'Body text.'+F,'multi-paragraph, one blank line':'A.\n\nB.'+F,
     'internal triple newline is not the boundary':'A.\n\n\nB.'+F}
neg={'two blank lines (PR 1591 case)':'Body text.\n'+F,'three blank lines':'Body text.\n\n'+F,
     'trailing spaces before boundary':'Body text.  '+F,'tab before boundary':'Body text.\t'+F,
     'no blank line':'Body text.\n---\n_Generated by [Claude Code](https://claude.ai/code)_',
     'trailing newline after footer':'Body text.'+F+'\n','missing footer':'Body text.',
     'footer twice':'Body.'+F+'\nMore.'+F,'empty content':F}
fail=0
for k,b in pos.items():
    r=footer_problem(b); ok=r is None; fail+=not ok; print('POS',k,'PASS' if ok else 'FAIL '+r)
for k,b in neg.items():
    r=footer_problem(b); ok=r is not None; fail+=not ok; print('NEG',k,'PASS' if ok else 'FAIL accepted')
# End to end: each tool refuses a malformed body before any network call. The network is made
# unreachable and the targets do not exist, so a defect could not send anything.
env=dict(os.environ,HTTPS_PROXY='http://127.0.0.1:9',https_proxy='http://127.0.0.1:9',GH_HOST='invalid.invalid',
         POST_HALT=os.path.join(tempfile.mkdtemp(),'HALT'))
for k,b in neg.items():
    p=os.path.join(tempfile.mkdtemp(),'b.md'); open(p,'w',encoding='utf-8',newline='').write(b)
    for cmd in (['python3','-I',W+'/post.py','999999',p],['python3','-I',W+'/mkpr.py','no-such-branch-x','main','t',p]):
        r=subprocess.run(cmd,capture_output=True,text=True,env=env)
        ok=r.returncode==4 and 'REFUSED' in r.stdout and not os.path.exists(env['POST_HALT'])
        fail+=not ok; print('E2E',os.path.basename(cmd[2]),k,'PASS' if ok else 'FAIL rc=%d %s'%(r.returncode,r.stdout[:80]))
print('RESULT', 'ALL PASS' if not fail else '%d FAILED'%fail); sys.exit(1 if fail else 0)
